//go:build amd64

package floats

// Maximum and Minimum kernels (maxmin.go), generated by go-asmgen
// (maxmin_amd64_gen.go) into maxmin_amd64.s. A kernel does the whole blocks of
// eight elements of slices whose length is a positive multiple of eight; the Go
// code finishes the last seven with the scalar rule. The AVX2 kernels share the
// gate of the other AVX2 kernels (hasAVX2FMA, kernels_amd64.go); without AVX2+FMA
// the SSE2 kernels run (SSE2 is the amd64 baseline). No kernel keeps a pointer:
// every stub is go:noescape.
//
//go:noescape
func maximumAVX2(dst, a, b []float64)

//go:noescape
func minimumAVX2(dst, a, b []float64)

//go:noescape
func maximumSSE2(dst, a, b []float64)

//go:noescape
func minimumSSE2(dst, a, b []float64)

func vmaximum(dst, a, b []float64) {
	n := len(a) &^ 7
	if n > 0 {
		if hasAVX2FMA {
			maximumAVX2(dst[:n], a[:n], b[:n])
		} else {
			maximumSSE2(dst[:n], a[:n], b[:n])
		}
	}
	maximumRef(dst[n:], a[n:], b[n:])
}

func vminimum(dst, a, b []float64) {
	n := len(a) &^ 7
	if n > 0 {
		if hasAVX2FMA {
			minimumAVX2(dst[:n], a[:n], b[:n])
		} else {
			minimumSSE2(dst[:n], a[:n], b[:n])
		}
	}
	minimumRef(dst[n:], a[n:], b[n:])
}
